                }
            }
        }
        return ans;
    }
};

class Solution {
    public int findLonelyPixel(char[][] picture) {
        int m = picture.length, n = picture[0].length;
        int[] rowCount = new int[m];
        int[] colCount = new int[n];
        for (int r = 0; r < m; r++) {
            for (int c = 0; c < n; c++) {
                if (picture[r][c] == 'B') {
                    rowCount[r]++;
                    colCount[c]++;
                }
            }
        }
        int ans = 0;
        for (int r = 0; r < m; r++) {
            for (int c = 0; c < n; c++) {
                if (picture[r][c] == 'B' && rowCount[r] == 1 && colCount[c] == 1) {
                    ans++;
                }
            }
        }
        return ans;
    }
}

/**
